<?php
session_start();if(!isset($_SESSION['user_id'])){header('Location: index.php');exit;}if(($_SESSION['role']??'')!=='student'){http_response_code(403);exit('Student access only.');}require 'config.php';$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$stmt=$pdo->prepare('SELECT a.*,u.name AS teacher_name FROM assignments a JOIN users u ON u.id=a.teacher_id WHERE a.id=?');$stmt->execute([$id?:0]);$a=$stmt->fetch();if(!$a){http_response_code(404);exit('Assignment not found.');}$message='';if($_SERVER['REQUEST_METHOD']==='POST'){$answer=trim($_POST['answer']??'');if($answer===''){$message='Please enter your submission before sending.';}else{$stmt=$pdo->prepare('INSERT INTO submissions(assignment_id,student_id,answer_text) VALUES(?,?,?) ON DUPLICATE KEY UPDATE answer_text=VALUES(answer_text),submitted_at=CURRENT_TIMESTAMP');$stmt->execute([$a['id'],$_SESSION['user_id'],$answer]);$message='Submission saved successfully.';}}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Submit assignment</title><link rel="stylesheet" href="assets/style.css"></head><body><header class="topbar"><a class="wordmark" href="dashboard.php">Assignment Portal</a><a href="logout.php">Log out</a></header><main class="form-container"><a class="back-link" href="dashboard.php">← Dashboard</a><p class="eyebrow"><?=htmlspecialchars($a['subject'])?></p><h1><?=htmlspecialchars($a['title'])?></h1><p class="muted">Due <?=htmlspecialchars($a['due_date'])?> · Teacher: <?=htmlspecialchars($a['teacher_name'])?></p><div class="description"><?=nl2br(htmlspecialchars($a['description']))?></div><?php if($message):?><div class="alert success"><?=htmlspecialchars($message)?></div><?php endif;?><form method="post"><label for="answer">Your answer / submission text</label><textarea id="answer" name="answer" rows="8" required placeholder="Write your answer here..."></textarea><button class="button full" type="submit">Submit assignment</button></form><p class="small muted">File uploads and teacher grading can be added in a later version.</p></main></body></html>
